package com.tekwatt.billing.controller;import com.tekwatt.billing.dto.*;import com.tekwatt.billing.service.BillingService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/bills")public class BillingController{private final BillingService service;public BillingController(BillingService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)BillResponse create(@Valid@RequestBody CreateBillRequest r){return service.create(r);}@GetMapping("/{id}")BillResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<BillResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PostMapping("/{id}/pay")BillResponse pay(@PathVariable UUID id){return service.pay(id);}@PostMapping("/{id}/void")BillResponse voidBill(@PathVariable UUID id){return service.voidBill(id);}}
